258	/**
259	 * Throws when applying `nextRole` to `memberId` would leave the organization
260	 * without an owner. Exported because both the demote and the remove path need
261	 * it, and the invariant must not be stated twice.
262	 */
263	export async function assertLastOwnerRetained(
264	  orgId: OrgId,
265	  memberId: MemberId,
266	  nextRole: Role,
267	): Promise<void> {
268	  if (nextRole === "owner") return;
269	
270	  const member = await memberRepo.findMemberById(orgId, memberId);
271	  if (!member || member.role !== "owner") return;
272	
273	  const page = await memberRepo.listMembers({
274	    orgId,
275	    role: "owner",
276	    limit: OWNER_SCAN_LIMIT,
277	    cursor: null,
278	  });
279	
280	  const remaining = page.items.filter((row) => row.id !== memberId);
281	  if (remaining.length === 0) {
282	    throw new Error(
283	      "An organization must keep at least one owner; transfer ownership first",
284	    );
285	  }
286	}
