'''import type { IsoTimestamp, MemberId, OrgId, UserId } from "@/types/common";
import type { Role } from "@/types/member";
import type {
  Organization,
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";''')
open(p,'a').write('''
function toHandover(row: OwnershipHandoverRow): OwnershipHandover {
  return {
    id: row.id,
    orgId: row.orgId as OrgId,
    fromUserId: row.fromUserId as UserId,
    toUserId: row.toUserId as UserId,
    status: row.status,
    expiresAt: row.expiresAt as IsoTimestamp,
    createdAt: row.createdAt as IsoTimestamp,
    resolvedAt: row.resolvedAt as IsoTimestamp | null,
  };
}

/**
 * The org's handover row still in `pending` status, lapsed or not — at most
 * one exists per org. Whether it has lapsed is the service's call.
 */
export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
  return row ? toHandover(row) : null;
}

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: IsoTimestamp,
  expiresAt: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt,
      createdAt,
      resolvedAt: null,
    })
    .returning()
    .get();
  return toHandover(row);
}

/**
 * Moves a pending handover to a terminal status. Returns `null` when the row
 * is no longer pending, so two racing resolutions cannot both win.
 */
export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: Exclude<OwnershipHandoverStatus, "pending">,
  resolvedAt: IsoTimestamp | null,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt })
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, handoverId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .returning()
    .get();
  return row ? toHandover(row) : null;
}

/** Withdraws the org's pending handover if `userId` is on either side of it. */
export async function cancelPendingHandoversInvolving(
  orgId: OrgId,
  userId: UserId,
  resolvedAt: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt })
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}

export interface OwnershipTransferResult {
  readonly organization: Organization;
  readonly fromUserId: UserId;
  readonly toUserId: UserId;
  /** Role changes actually applied, in the order they were made. */
  readonly roleChanges: readonly {
    readonly memberId: MemberId;
    readonly from: Role;
    readonly to: Role;
  }[];
}

/**
 * Completes a pending handover atomically: marks it accepted, promotes the new
 * owner, repoints `organizations.owner_id`, then demotes the previous owner.
 * The promotion comes first so the org holds an owner at every step. Returns
 * `null`, changing nothing, when the handover is no longer pending or the
 * offered user has no live membership.
 */
export async function acceptHandover(
  orgId: OrgId,
  handoverId: string,
  at: IsoTimestamp,
): Promise<OwnershipTransferResult | null> {
  return getDb().transaction((tx) => {
    const handover = tx
      .update(ownershipHandovers)
      .set({ status: "accepted", resolvedAt: at })
      .where(
        and(
          eq(ownershipHandovers.orgId, orgId),
          eq(ownershipHandovers.id, handoverId),
          eq(ownershipHandovers.status, "pending"),
        ),
      )
      .returning()
      .get();
    if (!handover) return null;

    const org = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    const liveMember = (userId: string) =>
      tx
        .select()
        .from(members)
        .where(
          and(
            eq(members.orgId, orgId),
            eq(members.userId, userId),
            isNull(members.archivedAt),
          ),
        )
        .get();

    const next = liveMember(handover.toUserId);
    if (!org || !next) {
      tx.rollback();
      return null;
    }
    const previous =
      org.ownerId === next.userId ? undefined : liveMember(org.ownerId);

    const roleChanges: {
      memberId: MemberId;
      from: Role;
      to: Role;
    }[] = [];

    if (next.role !== "owner") {
      tx.update(members)
        .set({ role: "owner", updatedAt: at })
        .where(eq(members.id, next.id))
        .run();
      roleChanges.push({
        memberId: next.id as MemberId,
        from: next.role,
        to: "owner",
      });
    }

    const updatedOrg = tx
      .update(organizations)
      .set({ ownerId: next.userId, updatedAt: at })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    if (previous && previous.role === "owner") {
      tx.update(members)
        .set({ role: "admin", updatedAt: at })
        .where(eq(members.id, previous.id))
        .run();
      roleChanges.push({
        memberId: previous.id as MemberId,
        from: "owner",
        to: "admin",
      });
    }

    return {
      organization: toOrganization(updatedOrg),
      fromUserId: org.ownerId as UserId,
      toUserId: next.userId as UserId,
      roleChanges,
    };
  });
}
''')

