'''import { toIsoTimestamp } from "@/types/common";
import { record } from "./activity-service";
import { notify } from "./notification-service";
import {
  actorEnvelope,
  envelope,
  NotFoundError,
  orgResource,
  requireFound,
} from "./_support";''')
sub(p,'import type { Organization, OrganizationSummary } from "@/types/organization";',
'''import type {
  Organization,
  OrganizationSummary,
  OwnershipHandover,
} from "@/types/organization";''')
open(p,'a').write('''
/** How long an ownership offer stays open. */
const HANDOVER_TTL_MS = 7 * 24 * 60 * 60 * 1000;

/** An offer made at T is open strictly before T + 7 days. */
function hasLapsed(handover: OwnershipHandover, now: Date): boolean {
  return now.getTime() >= Date.parse(handover.expiresAt);
}

/** The offer that can still be acted on, if any. */
async function findOpenHandover(
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover | null> {
  const pending = await orgRepo.findPendingHandover(orgId);
  return pending && !hasLapsed(pending, now) ? pending : null;
}

/**
 * Offering and withdrawing belong to the recorded owner alone — the owner
 * *role* is not enough, so this cannot be a `ROLE_MATRIX` row.
 */
async function assertRecordedOwner(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  if (org.ownerId !== actor.userId) {
    throw new PermissionDeniedError("org:update", {
      allowed: false,
      action: "org:update",
      resourceKind: "organization",
      reason: "denied_by_role",
    });
  }
  return org;
}

/**
 * Finds the offer addressed to the actor for accept/decline. Anyone but the
 * offered member sees nothing pending; the offered member learns of a lapse.
 */
async function requireOfferFor(
  actor: Actor,
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover> {
  const pending = await orgRepo.findPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (hasLapsed(pending, now)) {
    throw new OwnershipHandoverError("expired");
  }
  return pending;
}

export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  const org = await assertRecordedOwner(actor, orgId);

  if (toUserId === org.ownerId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active" || target.archivedAt !== null) {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const stale = await orgRepo.findPendingHandover(orgId);
  if (stale) {
    if (!hasLapsed(stale, now)) {
      throw new OwnershipHandoverError("pending_exists");
    }
    await orgRepo.resolveHandover(orgId, stale.id, "expired", null);
  }

  const handover = await orgRepo.insertHandover(
    orgId,
    actor.userId,
    toUserId,
    toIsoTimestamp(now),
    toIsoTimestamp(new Date(now.getTime() + HANDOVER_TTL_MS)),
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You were offered ownership of the workspace",
    body: `Accept to become the owner of ${org.name}`,
    href: "/settings/organization",
    actorId: actor.userId,
  });

  return handover;
}

export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const now = new Date();
  const handover = await requireOfferFor(actor, orgId, now);

  const result = await orgRepo.acceptHandover(
    orgId,
    handover.id,
    toIsoTimestamp(now),
  );
  if (!result) throw new OwnershipHandoverError("nothing_pending");

  for (const change of result.roleChanges) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: change.memberId,
      from: change.from,
      to: change.to,
    });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: result.fromUserId,
    toUserId: result.toUserId,
  });

  return result.organization;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const now = new Date();
  const handover = await requireOfferFor(actor, orgId, now);

  const declined = await orgRepo.resolveHandover(
    orgId,
    handover.id,
    "declined",
    toIsoTimestamp(now),
  );
  if (!declined) throw new OwnershipHandoverError("nothing_pending");
  return declined;
}

export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  await assertRecordedOwner(actor, orgId);

  const now = new Date();
  const open = await findOpenHandover(orgId, now);
  if (!open) throw new OwnershipHandoverError("nothing_pending");

  const canceled = await orgRepo.resolveHandover(
    orgId,
